const groups={},tests=[];let lines=[];const test=(name,run)=>tests.push({name,run});const log=(...args)=>lines.push(args.join(' '));
async function runTests(){for(const {name,run} of tests){if(CASE&&name!==CASE)continue;lines=[];try{await run()}catch(e){log('ERROR',e.name,e.message)}groups[name]=lines.slice()}return groups}
const attempt=fn=>{try{const v=fn();return v===undefined?'ok':v}catch(e){return e.name}};
const done=r=>new Promise(resolve=>r.addEventListener('loadend',()=>setTimeout(resolve,0),{once:true}));
const load=async(path,type='')=>{const r=new XMLHttpRequest();r.open('GET',path);r.responseType=type;const end=done(r);r.send();await end;return r};
const post=async body=>{const r=new XMLHttpRequest();r.open('POST','/echo');const end=done(r);r.send(body);await end;return JSON.parse(r.responseText)};
const xml=markup=>new DOMParser().parseFromString(markup,'application/xml');
const attrs=e=>Array.from(e.attributes,a=>[a.name,a.localName,a.prefix,a.namespaceURI,a.value].join(':')).join('|');
test('xml-attribute-create',()=>{for(const [ns,name] of [[null,'id'],['urn:a','p:id'],['','id'],['http://www.w3.org/2000/xmlns/','xmlns:p'],['http://www.w3.org/XML/1998/namespace','xml:lang']]){const a=document.createAttributeNS(ns,name);log(a.name,a.localName,a.prefix,a.namespaceURI,a.ownerElement,Reflect.set(a,'name','bad'),a.nodeName,a.nodeValue)}});
