test('xml-attribute-nodes',()=>{const a=document.createAttributeNS('urn:a','p:id'),e=document.createElement('div'),f=document.createElement('div');a.value='A';log(e.setAttributeNodeNS(a),a.ownerElement===e,attempt(()=>f.setAttributeNode(a)));const b=document.createAttributeNS('urn:a','q:id');b.value='B';log(e.setAttributeNode(b)===a,a.ownerElement,b.ownerElement===e,attrs(e));log(e.removeAttributeNode(b)===b,b.ownerElement,attempt(()=>e.removeAttributeNode(b)))});
