test('xml-attribute-case',()=>{const e=document.createElement('div');e.setAttribute('UPPER','a');e.setAttributeNS(null,'UPPER','b');log(attrs(e),e.getAttribute('UPPER'),e.getAttributeNS(null,'UPPER'));const a=document.createAttribute('UPPER'),b=document.createAttributeNS(null,'UPPER');log(a.name,b.name)});
