test('xml-attribute-shadow',()=>{const e=document.createElement('div');e.setAttributeNS('urn:a','p:id','A');const a=e.getAttributeNodeNS('urn:a','id');let calls=0;for(const name of ['name','localName','namespaceURI','prefix','ownerElement'])Object.defineProperty(a,name,{configurable:true,get(){calls++;return 'shadow'}});log(e.getAttributeNS('urn:a','id'));e.setAttributeNS('urn:a','q:id','B');log(e.getAttributeNS('urn:a','id'),calls);e.removeAttributeNS('urn:a','id');log(e.hasAttributeNS('urn:a','id'),calls)});
